  expect(await saved()).toMatchObject({x:8.125,y:-9.875});
  expect(await displayed()).toMatchObject({x:8.1,y:-9.85});
  p=await at(8.1,-9.85);await page.mouse.move(p.x,p.y);await page.mouse.down();
