export function alphaHit(r: Raster, x: number, y: number) {
  const px = Math.floor((x - r.x) * r.resolution),
    py = Math.floor((y - r.y) * r.resolution);
  return (
    px >= 0 &&
    py >= 0 &&
    px < r.canvas.width &&
